import fs from "node:fs";

const hook = "<p>Diese Seite ist Teil der lebenden Online-Referenz. Der Text basiert auf der zitierfähigen Originalfassung und wurde für die Webfassung strukturiert, verlinkt und gegen den aktuellen Begriffsstand eingeordnet.</p>";
const pages = {
  "referenz/kapitel-006-nachhaltigkeit-ist-keine-strategie/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-nachhaltigkeit"><h2 id="delta-nachhaltigkeit">Live-Reference-Delta 2026.3: Nachhaltigkeit als langfristige Wirkungsresilienz</h2><p>Die zitierfähige Originalfassung 2026.0 bleibt unverändert. Für die Live-Reference gilt: Nachhaltigkeit ist die langfristige Wirkungsresilienz des gekoppelten Systems Mensch–Planet–Demokratie. Sie ist weder bloßer Zielzustand noch Abfallprodukt oder Bericht.</p><p>Systemarchitektur beschreibt Regeln, Daten, Institutionen, Rückkopplungen und Strukturen. Systemresilienz beschreibt ihr dynamisches Verhalten unter Belastung. Maßgeblich sind stabilisierende, korrektive und regenerative Rückkopplungen, Rückstell- und Dämpfungsfähigkeit, Puffer, Wiederherstellung, Lernen, Anpassung, Transformation und Nicht-Externalisierung. Siehe <a href="../../begriffe/nachhaltigkeit/">Nachhaltigkeit</a> und <a href="../../blog/systemresilienz-statt-nachhaltigkeit/">den Journalartikel</a>.</p></section>`,
  "referenz/kapitel-018-wirkungsordnungen/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-wirkungsordnungen"><h2 id="delta-wirkungsordnungen">Live-Reference-Delta 2026.3: Architektur, Rückkopplung und Resilienz</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Für die aktuelle Einordnung gilt: Eine Wirkungsordnung wird nachhaltig, wenn ihre Architektur unter Belastung langfristige Wirkungsresilienz für Mensch, Planet und Demokratie ermöglicht.</p><p>Negative Rückkopplung kann systemtheoretisch stabilisieren und ist nicht mit negativer Wirkung gleichzusetzen. Zu prüfen sind Systemgrenze, Störung, Betroffene, Funktionen sowie Puffer, Korrektur, Regeneration und demokratische Rückkopplung. Schwere Schäden bleiben nicht kompensierbar.</p></section>`,
  "referenz/kapitel-019-nichttriviale-systeme/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-nichttriviale-systeme"><h2 id="delta-nichttriviale-systeme">Live-Reference-Delta 2026.3: Zustandsräume statt linearer Reaktion</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Nichttriviale Systeme verarbeiten Störungen aus ihrem Zustand, ihren Rückkopplungen und ihrer Geschichte. Die Stabilitätslandschaft macht dies als Attraktionsräume, Schwellen, Trajektorien und skalenübergreifende Einflüsse anschaulich.</p><p>Latitude, Resistance, Precariousness und Panarchy sind vier diagnostische Aspekte dieser Landschaft. Rückstell- und Dämpfungsfähigkeit erklären die Dynamik nach einer Störung; Anpassungs- und Transformationsfähigkeit bleiben davon getrennte, verwandte Fähigkeiten. Es handelt sich nicht um eine additive Rechenformel.</p></section>`,
  "referenz/kapitel-020-systemhebel-engpaesse-und-interdependenzen/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-systemhebel"><h2 id="delta-systemhebel">Live-Reference-Delta 2026.3: Hebel verändern auch die Stabilitätslandschaft</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Systemhebel wirken nicht nur auf einen aktuellen Zustand, sondern können Puffer, Regeln, Rückkopplungen, Barrieren und damit die Stabilitätslandschaft verändern. Anpassung verändert diese Bedingungen innerhalb eines bestehenden Zustandsraums; Transformation schafft bei Bedarf einen neuen tragfähigen Attraktor.</p><p>Bei jeder Hebelentscheidung sind Systemgrenze, Funktionen, Betroffene, mögliche Externalisierung und die Folgen auf Latitude, Resistance, Precariousness und Panarchy zu prüfen. Ein stabiler Teilsystemvorteil beweist noch keine Nachhaltigkeit des Gesamtsystems.</p></section>`,
  "referenz/kapitel-021-das-wirkungsrad/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-wirkungsrad"><h2 id="delta-wirkungsrad">Live-Reference-Delta 2026.3: Wirkungsrad und Resilienzdiagnostik</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Das Wirkungsrad kann Wirkungen, Rückkopplungen und Interdependenzen sichtbar machen. Für Resilienzdiagnostik ergänzt es die Frage, in welchem Attraktionsraum ein System liegt, wie nah seine Trajektorie an kritischen Schwellen verläuft und welche Puffer, Rückstell- und Dämpfungsmechanismen fehlen.</p><p>Die vier Walker-Dimensionen sind keine Punkte im Wirkungsrad und keine additive Formel. Wirkungsresilienz integriert ihre Diagnose mit Anpassung, Lernen und gegebenenfalls Transformation aus einem schädlichen Attraktor – normativ gebunden an Mensch, Planet und Demokratie.</p></section>`,
  "referenz/kapitel-023-wirkungsrisiko-und-wirkungsresilienz/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-wirkungsresilienz"><h2 id="delta-wirkungsresilienz">Live-Reference-Delta 2026.3: Wirkungsresilienz präzisiert</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Wirkungsresilienz bezeichnet die lernfähige und normativ an Mensch, Planet und Demokratie gebundene Resilienz des gekoppelten Systems. Sie verbindet die Resilienz eines MPD-tragfähigen Zustandsraums mit Anpassungs- und Transformationsfähigkeit und umfasst frühe Erkennung negativer Wirkungen und Störungen, Schutz und Wiederherstellung von Funktionen, Puffer, Regeneration, Lernen und Nicht-Externalisierung.</p><p>Die Diagnose fragt stets: Resilienz wovon, gegenüber welcher Störung, für wen und zur Erhaltung welcher Funktionen? Latitude, Resistance, Precariousness und Panarchy beschreiben die Stabilitätslandschaft; Rückstell- und Dämpfungsfähigkeit sind dynamische Ergänzungen, keine weiteren Walker-Punkte. Adaptability und Transformability sind bei Walker et al. verwandte eigenständige Fähigkeiten. Regimeresilienz ist keine Nachhaltigkeit. Quellen: <a href="https://doi.org/10.1146/annurev.es.04.110173.000245">Holling 1973</a>, <a href="https://doi.org/10.1007/s10021-001-0045-9">Carpenter et al. 2001</a>, <a href="https://www.ecologyandsociety.org/vol9/iss2/art5/">Walker et al. 2004</a>, <a href="https://doi.org/10.1016/j.gloenvcha.2006.04.002">Folke 2006</a> und <a href="https://doi.org/10.1017/9781009325844.029">IPCC 2022</a>.</p></section>`,
  "referenz/kapitel-065-resilienzstaat/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-resilienzstaat"><h2 id="delta-resilienzstaat">Live-Reference-Delta 2026.3: Resilienzstaat im MPD-Referenzrahmen</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Ein Resilienzstaat schützt nicht bloß institutionelle Beständigkeit. Nachhaltigkeit ist die langfristige Wirkungsresilienz des gekoppelten Systems Mensch–Planet–Demokratie: Grundfunktionen werden stabilisiert, korrigiert, wiederhergestellt und bei Bedarf transformiert.</p><p>Ein autoritärer Machtapparat kann regimeresilient sein und zugleich Menschenwürde, Wahrheit, Rechtsstaatlichkeit und demokratische Korrekturfähigkeit zerstören. Deshalb sind Systemgrenze, Funktionen, Betroffene, Nicht-Externalisierung und demokratische Rückkopplung ausdrücklich zu benennen.</p></section>`,
  "referenz/kapitel-095-globale-resilienz-sicherheit-und-kooperation/index.html": `
      <section class="callout live-reference-delta" aria-labelledby="delta-globale-resilienz"><h2 id="delta-globale-resilienz">Live-Reference-Delta 2026.3: Globale Wirkungsresilienz</h2><p>Die Originalfassung 2026.0 bleibt zitierfähig und unverändert. Sicherheit, Abschottung und Resilienz sind nicht gleichzusetzen. Nachhaltigkeit ist die langfristige Wirkungsresilienz von Mensch, Planet und Demokratie; globale Kooperation ist dort relevant, wo sie Funktionen schützt oder wiederherstellt, Puffer und Regeneration stärkt und Schäden nicht in andere Regionen oder Generationen verlagert.</p><p>Globale Resilienz fragt nach verbundenen Systemgrenzen, Störungen, Funktionen und Betroffenen. Sie verbindet Vorsorge, Wiederherstellung, Lernen, Anpassung und Transformation mit Nicht-Externalisierung und positiver Netto-Wirkung im Rahmen von SDGs, Agenda 2030 und SDG+.</p></section>`,
};

for (const [file, delta] of Object.entries(pages)) {
  let text = fs.readFileSync(file, "utf8");
  text = text.replaceAll("Online-Referenz 2026.2-live-reference", "Online-Referenz 2026.3-live-reference");
  text = text.replaceAll('data-version="2026.2-live-reference"', 'data-version="2026.3-live-reference"');
  const anchor = delta.match(/aria-labelledby="([^"]+)"/)?.[1];
  if (!anchor) throw new Error(`Delta-Anker fehlt: ${file}`);
  const existing = new RegExp(`<section class="callout live-reference-delta" aria-labelledby="${anchor}">[\\s\\S]*?</section>`);
  if (existing.test(text)) text = text.replace(existing, delta);
  else {
    if (!text.includes(hook)) throw new Error(`Live-Reference-Hinweis nicht gefunden: ${file}`);
    text = text.replace(hook, `${hook}${delta}`);
  }
  fs.writeFileSync(file, text);
}
console.log(`Live-Reference-Deltas aktualisiert: ${Object.keys(pages).length}`);
